INSERT INTO `course` VALUES (1,1,'认识广绣：历史与审美','从岭南丝绣传统到当代文创','/api/uploads/demo/course/guangxiu-history-cover.jpg',0.00,'梁雅文','33秒','BEGINNER','乳源瑶族刺绣是国家级非遗，主要流传于乳源必背、游溪、东坪等瑶族聚居地。它不用底稿，反面刺绣，依靠布纹来绣制纹样，配色鲜明，拥有三十多种固定形纹，2011年入选第三批国家级非遗名录。','在“世界过山瑶之乡”乳源，瑶族刺绣主要流传于必背、游溪、东坪镇等瑶族人聚居地。乳源瑶族刺绣以黑色、蓝色、白色布料为底布，以红、绿、黄、黑、白五种色线作线绣。刺绣前不需画底稿，刺绣时不必看正面，只从反面依着布纹就能绣出各种形纹和图案，常用技法有反面交叉、直行挑压和斜绣；线条以对角线、垂直线和平行线为主，固定形纹样式有30多种。瑶族刺绣于 2011年入选第三批国家级非物质文化遗产代表性项目名录。','https://xwzc.oss-cn-beijing.aliyuncs.com/b9dc280a0eb5ab6bed30fe51433c72bd.mp4',1878,658,1,10,'PUBLISHED','2026-07-10 22:56:23','2026-10-09 18:03:38',0),(2,1,'广绣常见吉祥纹样寓意','读懂牡丹、凤凰、蝴蝶与祥云','/api/uploads/demo/course/auspicious-pattern-cover.jpg',0.00,'陈晓绣','28 分钟','BEGINNER','本课程讲解广绣经典吉祥纹样的文化寓意，认识牡丹、金鱼、鸳鸯、鹤桃、蝴蝶等图案，读懂广绣纹样里藏着的传统吉祥暗语，感受岭南非遗广绣的美学与文脉。','广绣擅长将动植物纹样赋予吉祥寓意，一针一线皆是美好祝愿。牡丹象征荣华富贵；金鱼谐音金玉，寓意金玉满堂；鸳鸯代表夫妻恩爱和睦；仙鹤搭配桃子，寓意健康长寿；蝴蝶象征美好与自由。这些纹样承载岭南百姓对美好生活的向往，是广绣文化中极具特色的部分。','https://xwzc.oss-cn-beijing.aliyuncs.com/3.1.mp4',1436,525,1,20,'PUBLISHED','2026-07-10 22:56:24','2026-10-21 18:06:51',0),(3,2,'平针与铺针基础','从第一针开始理解广绣肌理','/api/uploads/demo/course/stitch-basics-cover.jpg',19.90,'陈晓绣','2 课时','BASIC','通过放大示范讲解平针、铺针的下针方向、丝线排列和色彩衔接。','课程包括工具准备、绷架使用、丝线劈分、针脚排列和常见问题处理。完成后可独立练习基础花瓣和叶片。','https://xwzc.oss-cn-beijing.aliyuncs.com/4.1.mp4',990,273,0,30,'PUBLISHED','2026-07-10 22:56:24','2026-10-09 17:59:00',0),(4,2,'牡丹与凤凰构图方法','传统主纹样的层次、动势与留白','/api/uploads/demo/course/peony-phoenix-composition-cover.jpg',29.90,'林志成','55 分钟','ADVANCED','《苏绣教程：火凤凰讲解版，从用色到劈丝》','讲解苏绣火凤凰的制作过程，涵盖色彩搭配、劈丝技巧及基础绣制方法，帮助初学者了解苏绣技法与凤凰图案的表现方式。','https://xwzc.oss-cn-beijing.aliyuncs.com/5.1.mp4',767,185,0,40,'PUBLISHED','2026-07-10 22:56:24','2026-10-09 11:51:26',0),(5,3,'AI 辅助广绣纹样设计','从关键词到可用纹样的完整流程','/api/uploads/demo/course/ai-pattern-design-cover.jpg',0.00,'周可心','45 分钟','BASIC','《一键AI生成刺绣贴图，设计效率翻倍》','介绍利用 AI 一键生成刺绣贴图的方法，展示从创意构思到图案生成的设计流程，帮助用户快速制作刺绣图案，提高设计效率。','https://xwzc.oss-cn-beijing.aliyuncs.com/6.1.mp4',2394,939,1,50,'PUBLISHED','2026-07-10 22:56:24','2026-10-09 17:59:32',0),(6,3,'文创产品纹样落地','把一张纹样应用到包袋、丝巾和纸品','/api/uploads/demo/course/product-application-cover.jpg',19.90,'周可心','38 分钟','BASIC','纹样中国','课程通过帆布袋、方巾、杯垫和明信片案例，说明中心构图、连续纹样和边饰纹样的不同适配方式。','https://xwzc.oss-cn-beijing.aliyuncs.com/7.1.mp4',1191,409,1,60,'PUBLISHED','2026-07-10 22:56:24','2026-10-09 18:03:44',0),(7,1,'刺绣',NULL,'https://xwzc.oss-cn-beijing.aliyuncs.com/COURSE/da90142cae944754b1d0920c6e838051.jpg',0.00,'深入中国','6分钟','中',NULL,NULL,'https://www.bilibili.com/video/BV14v4y1L7b2/',1,1,1,0,'PUBLISHED','2026-09-22 13:10:46','2026-09-22 13:12:04',1),(8,1,'刺绣',NULL,'https://xwzc.oss-cn-beijing.aliyuncs.com/COURSE/d72acd215bb64143ad00d3acd013f55b.png',0.00,'Liu',NULL,'高','本课程速览苏、湘、粤、蜀中国四大名绣的精湛技艺，通过微距镜头拆解特色针法，了解新一代传承人创新表达，感受非遗刺绣跨越千年的独特魅力。',NULL,'https://xwzc.oss-cn-beijing.aliyuncs.com/1.1.mp4',35,19,1,8,'PUBLISHED','2026-09-29 19:07:56','2026-10-21 19:22:37',0),(10,1,'认识广绣：历史与审美',NULL,NULL,0.00,NULL,NULL,NULL,'广绣是国家级非物质文化遗产，自带独特岭南气韵。当代传承人不断创新，把传统针法和现代审美结合，让广绣走出博物馆，用新潮形式传承非遗，感受一针一线的东方匠心。\n','广绣，国家级非物质文化遗产，浸润着独有的岭南气韵。古老技艺不再束之高阁，传承人不断探索创新，将传统针法与当代审美相融，让广绣走出博物馆，解锁非遗更多新潮打开方式，感受一针一线间的东方匠心与文化魅力。\n','https://xwzc.oss-cn-beijing.aliyuncs.com/10e9b187c82425afbbede46e177a899b.mp4',0,0,0,0,'DRAFT','2026-10-09 10:58:02','2026-10-09 11:00:55',1),(11,1,'广绣',NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,'https://xwzc.oss-cn-beijing.aliyuncs.com/10e9b187c82425afbbede46e177a899b.mp4',0,0,0,0,'DRAFT','2026-10-09 11:00:14','2026-10-09 11:00:57',1);
/*!40000 ALTER TABLE `course` ENABLE KEYS */;
UNLOCK TABLES;

