INSERT INTO `course_category` VALUES (1,NULL,'广绣文化入门','了解广绣历史、审美特点、代表题材及岭南文化背景。',10,1,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(2,NULL,'针法与纹样技艺','学习广绣常见针法、配色、构图与传统吉祥纹样表达。',20,1,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(3,NULL,'数字创作实践','使用数字工具和 AI 完成纹样创作、产品适配与文创设计。',30,1,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(4,NULL,'数字创作实践','使用数字工具和',0,1,'2026-07-29 20:05:55','2026-07-29 20:06:39',0);
