  `pay_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '实付金额',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'WAIT_PAY' COMMENT '订单状态：WAIT_PAY待支付 WAIT_CONFIRM待接单 PRODUCING制作中 WAIT_DELIVERY待发货 DELIVERED已发货 COMPLETED已完成 CANCELLED已取消',
  `pay_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'UNPAID' COMMENT '支付状态：UNPAID未支付 PAID已支付 REFUNDED已退款',
