--
-- Table structure for table `pattern`
--

DROP TABLE IF EXISTS `pattern`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pattern` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '纹样ID，自增主键',
  `generation_id` bigint DEFAULT NULL COMMENT 'AI生成记录ID，对应pattern_generation.id',
  `user_id` bigint NOT NULL COMMENT '所属用户ID，对应user.id',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样标题',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '纹样原图URL',
  `thumbnail_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样缩略图URL',
  `keyword` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成关键词快照',
  `style` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样风格',
  `elements` json DEFAULT NULL COMMENT '纹样元素数组快照',
  `color_theme` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '颜色主题',
  `usage_scene` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用场景',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样说明',
  `is_saved` tinyint NOT NULL DEFAULT '1' COMMENT '是否已保存到我的纹样：1是 0否',
  `is_favorite` tinyint NOT NULL DEFAULT '0' COMMENT '是否收藏：1是 0否',
  `is_recommend` tinyint NOT NULL DEFAULT '0' COMMENT '是否首页推荐：1是 0否',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞或收藏热度数量',
  `use_count` int NOT NULL DEFAULT '0' COMMENT '被应用到商品定制的次数',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NORMAL' COMMENT '状态：NORMAL正常 HIDDEN隐藏 DELETED删除',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删除 1已删除',
  PRIMARY KEY (`id`),
  KEY `idx_pattern_generation_id` (`generation_id`),
  KEY `idx_pattern_user_id` (`user_id`),
  KEY `idx_pattern_recommend` (`is_recommend`),
  KEY `idx_pattern_status` (`status`),
  CONSTRAINT `fk_pattern_generation` FOREIGN KEY (`generation_id`) REFERENCES `pattern_generation` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pattern_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=219 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='纹样表';
/*!40101 SET character_set_client = @saved_cs_client */;

