--
-- Table structure for table `pattern_generation`
--

DROP TABLE IF EXISTS `pattern_generation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pattern_generation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '生成记录ID，自增主键',
  `user_id` bigint NOT NULL COMMENT '发起生成的用户ID，对应user.id',
  `keyword` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户输入关键词',
  `style` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样风格：classic广绣经典 new_chinese新中式 embroidery刺绣风等',
  `elements` json DEFAULT NULL COMMENT '纹样元素数组，例如牡丹、凤凰、祥云等',
  `color_theme` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '颜色主题，例如国风雅韵、富贵华彩等',
  `usage_scene` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用场景：product文创商品 clothing服饰 home家居等',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户补充描述',
  `reference_image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '参考图URL',
  `prompt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '最终发送给AI模型的提示词',
  `generate_count` int NOT NULL DEFAULT '1' COMMENT '本次生成图片数量',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '生成状态：PENDING生成中 SUCCESS成功 FAILED失败',
  `progress` int NOT NULL DEFAULT '0' COMMENT '生成进度0-100',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成失败原因',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '最后更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删除 1已删除',
  PRIMARY KEY (`id`),
  KEY `idx_generation_user_id` (`user_id`),
  KEY `idx_generation_status` (`status`),
  CONSTRAINT `fk_generation_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI纹样生成记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pattern_generation`
--

