DROP TABLE IF EXISTS `production_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工单ID，自增主键',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0未删除 1已删除',
  `order_no` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '工单号，如PO20261015153012-47',
  `user_id` bigint NOT NULL COMMENT '提交打样的用户ID，对应user.id',
  `user_nickname` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提交时用户昵称快照',
  `factory_name` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '承接工坊名称',
  `pattern_id` bigint DEFAULT NULL COMMENT '关联纹样ID，对应pattern.id',
  `pattern_title` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样标题快照',
  `pattern_image_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样图URL',
  `style` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样风格，如广绣经典',
  `stitch_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'OUTLINE' COMMENT '针法：OUTLINE轮廓走针 SATIN平包针 TATAMI他他米针',
  `fabric_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '面料类型(canvas/cotton/silk，张力补偿参数)',
  `design_hash` varchar(72) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '纹样设计数字指纹(SHA-256)',
  `dst_hash` varchar(72) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'DST打版文件指纹(SHA-256)',
  `stitch_image_url` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '针脚路径可视化图URL',
  `dst_file_url` varchar(512) COLLATE utf8mb4_general_ci NOT NULL COMMENT '工业级DST文件下载地址',
  `stitch_count` int NOT NULL DEFAULT '0' COMMENT '针数（打版引擎实测）',
  `file_size` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'DST文件大小，如118 KB',
  `quote_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '动态报价：基础材料费+针数×单价',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '工单状态：PENDING待生产 IN_PRODUCTION生产中 COMPLETED已完成',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_po_order_no` (`order_no`),
  KEY `idx_po_user_id` (`user_id`),
  KEY `idx_po_status` (`status`),
  CONSTRAINT `fk_po_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='工厂端生产工单表';
