INSERT INTO `prompt_template` VALUES (1,'广绣经典牡丹凤凰','classic','product','富贵华彩','以{keyword}为核心主题，融合广绣经典牡丹、凤凰、祥云元素，采用细密刺绣针法质感，构图饱满而有层次，主色使用{colorTheme}，适合{usageScene}文创产品，高清平面纹样，背景干净，不出现文字和水印。',1,10,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(2,'新中式岭南花窗','new_chinese','home','岭南雅韵','围绕{keyword}设计新中式广绣纹样，融入岭南花窗、木棉花与水波纹元素，线条简洁、留白克制，色彩采用{colorTheme}，传统纹样与现代几何结合，适合家居和礼赠应用，高清无文字。',1,20,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(3,'连续纹样织物','embroidery','clothing','清雅柔和','将{keyword}转化为可无缝平铺的广绣连续纹样，元素大小均衡、重复节奏自然，保留丝线光泽与针脚层次，颜色使用{colorTheme}，适合丝巾、布料和包袋印花，正视图，高清，无边框。',1,30,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(4,'圆形团花构图','classic','product','朱红鎏金','以{keyword}为中心制作圆形团花纹样，外围结合如意云头、缠枝花卉和蝙蝠吉祥纹，构图对称完整，广绣金银线质感明显，主色为{colorTheme}，适合杯垫、徽章和礼盒封面，透明感背景，无文字。',1,40,'2026-07-10 22:56:23','2026-07-10 22:56:23',0),(5,'国潮醒狮纹样','guochao','product','醒狮华彩','以{keyword}为主题，创作年轻化国潮广绣纹样，融入广东醒狮、木棉花、祥云与岭南色彩，视觉有力量但不过度复杂，使用{colorTheme}，适合抱枕、帆布袋和明信片，高清插画纹样，无品牌标识。',1,50,'2026-07-10 22:56:23','2026-07-31 17:41:08',0),(6,'广绣牡丹帆布袋','classic','product','富贵华彩','以醒狮为主题，采用广绣风格，配色为 {colorTheme}。',1,10,'2026-07-31 19:18:06','2026-07-31 19:18:06',0);
